/* Inglese — ampliamento Z1: 8 argomenti (L0–L3). */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order, listen, card } = C;
  const T = (o) => C.addTopic(Object.assign({ subject: 'eng', minutes: 20 }, o));

  /* ---------- L0 ---------- */
  T({ id: 'eng-l0-be-have-basics', stage: 'L0', prereq: [], title: 'Essere e avere: to be, have got e risposte brevi', summary: 'Forme di to be e have (got), negazioni, domande e short answers.',
    objectives: ['Coniugare to be e have / have got in frasi affermative, negative e interrogative', 'Rispondere con le short answers (Yes, I am. / No, she doesn’t.)', 'Evitare gli errori tipici degli italiani (I have 20 years, He have)'],
    pages: [
      { h: 'Obiettivo', b: 'I verbi **to be** (essere) e **to have** (avere) sono i più usati dell’inglese. Funzionano in modo diverso dall’italiano: l’inglese usa *be* anche dove noi usiamo *avere* (età, fame, freddo). Qui impari forme, domande e **risposte brevi**.' },
      { h: 'To be: presente', b: '- {{en-GB|I am a student.}} (contratto: **I’m**)\n- {{en-GB|You are late.}} (**you’re**)\n- {{en-GB|He is tired. / She is at home. / It is cold.}} (**he’s, she’s, it’s**)\n- {{en-GB|We are friends. / They are from Italy.}} (**we’re, they’re**)\n\n**Negativo**: si aggiunge *not*: {{en-GB|I’m not ready. / She isn’t here. / They aren’t English.}}\n\n**Domanda**: si inverte: {{en-GB|Are you hungry? / Is he a doctor?}}' },
      { h: 'Be al posto di «avere»', b: 'In inglese con *be* si dicono:\n- **età**: {{en-GB|I’m thirty years old.}} (non *I have thirty years*)\n- **sensazioni**: {{en-GB|I’m hungry, thirsty, cold, hot, afraid, right, wrong.}}\n- **provenienza**: {{en-GB|I’m from Naples.}}\n\nDomanda sull’età: {{en-GB|How old are you?}}' },
      { h: 'Have e have got', b: '**Possesso** (britannico): **have got** = **have**.\n- {{en-GB|I have got a brother. / I’ve got a brother.}}\n- {{en-GB|She has got blue eyes. / She’s got blue eyes.}}\n- Negativo: {{en-GB|I haven’t got a car.}}  Domanda: {{en-GB|Have you got a pen?}}\n\nNel inglese americano si preferisce **have** con *do*: {{en-US|Do you have a pen? I don’t have a car.}}\n\nAttenzione: **he/she/it → has**: {{en-GB|He has a dog.}} (mai *he have*).' },
      { h: 'Have come verbo normale', b: 'Con azioni e abitudini, **have** si comporta come un verbo ordinario e usa **do/does**:\n- {{en-GB|I have breakfast at seven.}}\n- {{en-GB|Does she have lunch at work?}}\n- {{en-GB|We don’t have a shower in the morning.}}\n\nAnche: *have a coffee, have a good time, have a look*. Qui **have got** NON si usa.' },
      { h: 'Short answers', b: 'Alle domande si risponde con **Yes/No + soggetto + ausiliare**, senza ripetere il verbo principale:\n- {{en-GB|Are you tired? — Yes, I am. / No, I’m not.}}\n- {{en-GB|Is she a teacher? — Yes, she is. / No, she isn’t.}}\n- {{en-GB|Have you got a car? — Yes, I have. / No, I haven’t.}}\n- {{en-GB|Does he have a dog? — Yes, he does. / No, he doesn’t.}}\n\nNella risposta affermativa **non si contrae**: *Yes, I am* (non *Yes, I’m*).' },
      { h: 'Esempio guidato', b: 'Presentati: *Sono Marco, ho 25 anni, sono di Torino. Ho una sorella. Non ho una macchina.*\n\n**I’m Marco. I’m 25. I’m from Turin. I’ve got a sister. I haven’t got a car.**\n\nDomanda del compagno: *Have you got a car?* → **No, I haven’t.**\n\nControllo: age con be, possesso con have got, risposta breve con l’ausiliare giusto.' },
      { h: 'Errori comuni', b: '- *I have 25 years.* → {{en-GB|I’m 25 (years old).}}\n- *He have a car.* → {{en-GB|He has a car.}}\n- *I am agree.* → {{en-GB|I agree.}} (*agree* non vuole be)\n- *Do you have…? — Yes, I have.* → {{en-GB|Yes, I do.}}\n- *I’m have a cold.* → {{en-GB|I’ve got a cold.}}\n- *She doesn’t has* → {{en-GB|She doesn’t have.}}' },
      { h: 'Riepilogo', b: '- be: am, are, is; negativo con *not*, domanda per inversione.\n- Età e sensazioni con be.\n- have / have got = possesso; has con he/she/it.\n- Azioni: have + do/does.\n- Short answers con l’ausiliare, senza contrazione nel «sì».' }
    ],
    exercises: [
      mc('My sister ___ 22 years old.', ['has', 'have', 'is', 'are'], 2),
      mc('___ she got a brother?', ['Is', 'Has', 'Does', 'Have'], 1),
      fill('Complete: He ___ (have) two cats.', ['has'], 'Con he/she/it il presente di have è has.'),
      mc('Are you from Spain? — No, ___.', ['I amn’t', 'I’m not', 'I don’t', 'I haven’t'], 1),
      order('Metti in ordine', ['Have', 'you', 'got', 'a', 'pen', '?'], 'Have got: domanda per inversione.'),
      mc('Do you have a car? — Yes, ___.', ['I have', 'I am', 'I do', 'I does'], 2, 'La domanda usa do: risposta con do.'),
      listen('She isn’t at home. She’s at work.', 'en-GB', 'Where is she?', ['At home', 'At school', 'At work', 'In a shop'], 2, 'Isn’t at home: non è a casa.')
    ],
    test: [
      mc('How do you say «Ho fame» in English?', ['I have hunger.', 'I am hungry.', 'I have hungry.', 'I do hungry.'], 1),
      mc('Which sentence is correct?', ['He have a bike.', 'He has got a bike.', 'He haves a bike.', 'He is have a bike.'], 1),
      mc('Is your mother a teacher? — Yes, ___.', ['she’s', 'she is', 'she does', 'she has'], 1),
      fill('Complete: They ___ (not / be) at school today.', ['aren’t', 'are not', 'arent'], 'Negativo di are: aren’t.'),
      mc('Which sentence is NOT correct?', ['I’m cold.', 'I’m thirty.', 'I have thirty years.', 'I’ve got a cold.'], 2)
    ],
    cards: [card('c1', 'avere fame', 'to be hungry', 'I’m hungry.'), card('c2', 'avere sete', 'to be thirsty', 'Are you thirsty?'), card('c3', 'avere freddo', 'to be cold', 'She’s cold.'), card('c4', 'avere caldo', 'to be hot', 'It’s hot today.'),
      card('c5', 'avere … anni', 'to be … years old', 'He’s ten years old.'), card('c6', 'ho (possesso)', 'I’ve got', 'I’ve got a sister.'), card('c7', 'non ho', 'I haven’t got', 'I haven’t got time.'), card('c8', 'fare colazione', 'to have breakfast', 'I have breakfast at eight.'), card('c9', 'divertirsi', 'to have a good time', 'We had a good time.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'Meet my family', text: 'Hi, I’m Anna. I’m twenty-six and I’m from Bologna. I’ve got one brother and one sister. My brother is fifteen, and he’s very tall. My sister has two children, so I’m an aunt! We haven’t got a dog, but we’ve got two cats. In the morning, I have breakfast with my mum. My dad isn’t at home; he’s at work.',
      qs: [{ q: 'How old is Anna?', o: ['Fifteen', 'Twenty-six', 'Thirty', 'Sixteen'], a: 1, kind: 'explicit' }, { q: 'Which pets does the family have?', o: ['A dog', 'Two cats', 'A dog and a cat', 'No pets'], a: 1, kind: 'explicit' }, { q: 'What can we understand about Anna’s sister?', o: ['She is a mother', 'She is fifteen', 'She is single', 'She lives alone'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'I’m twenty years old and I’m from Rome.', lang: 'en-GB' }, { text: 'She has got two brothers.', lang: 'en-US' }, { text: 'Are you hungry? Yes, I am.', lang: 'en-AU' }],
    shadowing: [{ text: 'I’ve got a brother and a sister.', lang: 'en-GB', tip: 'I’ve: /aɪv/; accento su brother e sister.' }, { text: 'Is he a doctor? No, he isn’t.', lang: 'en-US', tip: 'Intonazione ascendente nella domanda, discendente nella risposta.' }, { text: 'Do you have a pen? Yes, I do.', lang: 'en-AU', tip: 'Do debole nella domanda, forte nella risposta.' }],
    speaking: [{ prompt: 'Introduce yourself: name, age, where you are from, family.', model: 'I’m Luca. I’m twenty-eight and I’m from Milan. I’ve got one sister. She’s a nurse. I haven’t got any brothers.' }, { prompt: 'Ask a partner three yes/no questions with be and have, and answer with short answers.', model: 'Are you tired? — No, I’m not. Have you got a car? — Yes, I have. Does she have a dog? — No, she doesn’t.' }] });

  T({ id: 'eng-l0-time-dates-numbers', stage: 'L0', prereq: ['eng-l0-habits'], title: 'Ore, date e numeri', summary: 'Dire l’ora, i giorni, i mesi, le date, i numeri grandi e i prezzi.',
    objectives: ['Dire e chiedere l’ora in modi diversi', 'Leggere date, anni e numeri ordinali', 'Pronunciare numeri e prezzi senza confondere -teen e -ty'],
    pages: [
      { h: 'Obiettivo', b: 'Ore, date e numeri servono ogni giorno: appuntamenti, viaggi, acquisti. In inglese ci sono diversi modi di dire l’ora e le date si leggono in modo particolare. Imparerai a **capire e dire** queste informazioni con sicurezza.' },
      { h: 'L’ora', b: 'Domanda: {{en-GB|What time is it? / Have you got the time?}}\n\n- **7:00** → {{en-GB|It’s seven o’clock.}}\n- **7:15** → {{en-GB|It’s quarter past seven.}}\n- **7:30** → {{en-GB|It’s half past seven.}}\n- **7:45** → {{en-GB|It’s quarter to eight.}}\n- **7:10** → {{en-GB|It’s ten past seven.}}\n- **7:50** → {{en-GB|It’s ten to eight.}}\n\n**past** = dopo (fino a 30), **to** = meno (da 30 in poi). Modo digitale: *seven forty-five*. Per distinguere: **a.m.** (mattina) e **p.m.** (pomeriggio/sera).' },
      { h: 'A che ora?', b: 'Si usa **at**: {{en-GB|The film starts at nine.}} {{en-GB|I get up at half past six.}}\n\nParole utili: *noon* (mezzogiorno), *midnight* (mezzanotte), *in the morning / afternoon / evening* ma **at night**.\n\nDomanda: {{en-GB|What time does the train leave?}}' },
      { h: 'Giorni, mesi e date', b: 'Giorni: *Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday*. I giorni e i mesi si scrivono con la **maiuscola**.\n\nDate: si usano gli **ordinali** (first, second, third, fourth… twentieth, twenty-first…):\n- {{en-GB|My birthday is on the fifth of June.}} (scritto *5 June*)\n- {{en-US|My birthday is on June fifth.}} (americano: mese + giorno)\n\nPreposizioni: **on** + giorno/data (*on Monday, on 5 June*), **in** + mese/anno (*in June, in 2024*).\n\nAnni: *1999* = *nineteen ninety-nine*; *2025* = *twenty twenty-five*; *2008* = *two thousand and eight*.' },
      { h: 'Numeri', b: '- 13–19 finiscono in **-teen** (accento sulla seconda parte: thirTEEN); 20–90 in **-ty** (THIRty).\n- Composti con trattino: {{en-GB|twenty-one, sixty-five.}}\n- **100** = *a hundred*; **1,000** = *a thousand*; **1,000,000** = *a million*. Si usa *and* in inglese britannico: {{en-GB|two hundred and fifty.}}\n- **0** = *zero* (numeri), *nought* (britannico), *oh* (telefono).\n- Decimali: **3.5** = *three point five*. Frazioni: *a half, a quarter*.\n- Prezzi: {{en-GB|It costs £4.50 — four pounds fifty.}}' },
      { h: 'Esempio guidato', b: 'Annuncio: *Il treno per Londra parte alle 14:45 di venerdì 3 maggio e costa 35 sterline.*\n\n**The train to London leaves at quarter to three p.m. (two forty-five) on Friday, the third of May. It costs thirty-five pounds.**\n\nControllo: at + ora, on + giorno, ordinale per la data, -ty per 35 (THIRty-five).' },
      { h: 'Errori comuni', b: '- *It’s the half past seven.* → {{en-GB|It’s half past seven.}} (niente articolo)\n- *At Monday* → {{en-GB|On Monday.}}\n- *In 5 June* → {{en-GB|On 5 June.}}\n- *I’m born in 1990* → {{en-GB|I was born in 1990.}}\n- Confondere *fifteen* e *fifty*: ascolta l’accento.\n- *Two hundreds people* → {{en-GB|Two hundred people.}} (hundred non prende -s dopo un numero)' },
      { h: 'Riepilogo', b: '- Ora: o’clock, past, to, half past, quarter.\n- at + ora, on + giorno/data, in + mese/anno.\n- Date con ordinali: the fifth of June.\n- -teen (thirTEEN) vs -ty (THIRty).\n- Hundred / thousand / million senza -s dopo un numero.' }
    ],
    exercises: [
      mc('7:45 is…', ['half past seven', 'quarter to eight', 'quarter past seven', 'quarter to seven'], 1),
      mc('The lesson starts ___ nine o’clock.', ['in', 'on', 'at', 'to'], 2),
      mc('Which is the correct date?', ['the five of June', 'the fifth of June', 'the fiveth of June', 'five June the'], 1),
      fill('Complete: My birthday is ___ 12 March. (preposition)', ['on'], 'Date: on + data.'),
      order('Metti in ordine', ['What', 'time', 'does', 'the', 'shop', 'open', '?'], 'Domanda con does + verbo base.'),
      listen('The bus leaves at half past six.', 'en-GB', 'What time does the bus leave?', ['6:15', '6:30', '6:45', '7:30'], 1, 'Half past six = 6:30.'),
      mc('How do you say 1,500?', ['one thousand five hundred', 'one hundred five', 'fifteen thousand', 'fifty hundred'], 0)
    ],
    test: [
      mc('Which sentence is correct?', ['I was born on 1990.', 'I was born in 1990.', 'I am born in 1990.', 'I born in 1990.'], 1),
      mc('«Thirteen» and «thirty» differ because…', ['thirteen is stressed on -teen', 'thirty is stressed on -ty', 'they sound identical', 'thirteen has no stress'], 0),
      mc('Which is the correct preposition? ___ Friday evening', ['In', 'At', 'On', 'To'], 2),
      fill('Write in words: 4.5 → four ___ five.', ['point'], 'Decimali: point.'),
      mc('«It’s ten to eight» means…', ['7:50', '8:10', '7:10', '8:50'], 0)
    ],
    cards: [card('c1', 'mezzogiorno', 'noon', 'We eat at noon.'), card('c2', 'mezzanotte', 'midnight', 'The party ends at midnight.'), card('c3', 'un quarto d’ora', 'a quarter of an hour', 'It takes a quarter of an hour.'), card('c4', 'mezz’ora', 'half an hour', 'half an hour late'),
      card('c5', 'compleanno', 'birthday', 'Happy birthday!'), card('c6', 'settimana', 'week', 'next week'), card('c7', 'weekend', 'weekend', 'at the weekend'), card('c8', 'primo (ordinale)', 'first', 'the first of May'), card('c9', 'mille', 'a thousand', 'a thousand people')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A train announcement', text: 'Good morning. The train to Manchester leaves from platform nine at quarter to ten. It is not the ten o’clock train; that one leaves at ten past ten from platform fourteen. Tickets cost forty pounds, and they are cheaper on Sundays. This week the station opens at six in the morning, but on the twentieth of December it will open at five.',
      qs: [{ q: 'What time does the Manchester train leave?', o: ['9:15', '9:45', '10:10', '10:00'], a: 1, kind: 'explicit' }, { q: 'How much do the tickets cost?', o: ['£14', '£40', '£90', '£15'], a: 1, kind: 'explicit' }, { q: 'What can you infer about the platform for the 10:10 train?', o: ['It is different from platform nine', 'It is the same platform', 'It does not exist', 'It is closed'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'The film starts at half past eight.', lang: 'en-GB' }, { text: 'My birthday is on the fifth of June.', lang: 'en-US' }, { text: 'It costs fifteen pounds fifty.', lang: 'en-AU' }],
    shadowing: [{ text: 'What time does the train leave?', lang: 'en-GB', tip: 'Intonazione discendente nelle wh-questions.' }, { text: 'It’s quarter to nine on Friday morning.', lang: 'en-US', tip: 'Quarter to: to debole /tə/.' }, { text: 'I was born in nineteen ninety-five.', lang: 'en-AU', tip: 'Leggi l’anno in due coppie di cifre.' }],
    speaking: [{ prompt: 'Tell your daily routine with times (get up, work, lunch, go to bed).', model: 'I get up at quarter to seven. I start work at half past eight. I have lunch at one o’clock, and I go to bed at about eleven.' }, { prompt: 'Say your date of birth and the dates of two important events.', model: 'I was born on the twelfth of March, nineteen ninety-eight. My sister’s wedding is on the twentieth of September.' }] });

  /* ---------- L1 ---------- */
  T({ id: 'eng-l1-past-continuous-simple', stage: 'L1', prereq: ['eng-l0-past'], title: 'Past continuous e past simple: contrasto', summary: 'was/were doing per lo sfondo, past simple per l’azione; when e while.',
    objectives: ['Formare il past continuous (was/were + -ing)', 'Scegliere tra past continuous e past simple nello stesso racconto', 'Usare when e while correttamente'],
    pages: [
      { h: 'Obiettivo', b: 'Quando racconti qualcosa al passato, usi due «piani»: lo **sfondo** (cosa stava succedendo) e le **azioni** (cosa è successo). Il past continuous descrive lo sfondo, il past simple le azioni. In italiano è la differenza tra *imperfetto* e *passato prossimo/remoto*: *Mentre mangiavo, è squillato il telefono.*' },
      { h: 'Forma del past continuous', b: '**was / were + verbo -ing**\n- {{en-GB|I was working. / She was reading.}}\n- {{en-GB|We were watching TV. / They were playing.}}\n\nNegativo: {{en-GB|I wasn’t sleeping. / They weren’t listening.}}\nDomanda: {{en-GB|Were you waiting? — Yes, I was. / No, I wasn’t.}}\n\nRegola ortografica: *run → running*, *make → making*, *lie → lying*.' },
      { h: 'Quando si usa', b: '1. **Azione in corso in un momento passato**: {{en-GB|At eight o’clock I was having breakfast.}}\n2. **Sfondo di un racconto**: {{en-GB|It was raining and people were hurrying home.}}\n3. **Due azioni parallele**: {{en-GB|I was cooking while he was watching TV.}}\n\nIl past simple dice invece **cosa è accaduto**, una dopo l’altra: {{en-GB|I opened the door, saw the cat and smiled.}}' },
      { h: 'Il contrasto: azione interrotta', b: 'Un’azione breve (past simple) **interrompe** una lunga (past continuous):\n- {{en-GB|I was walking home when it started to rain.}}\n- {{en-GB|While she was cooking, the phone rang.}}\n- {{en-GB|He was driving when he saw the accident.}}\n\n**when** + past simple (l’evento), **while** + past continuous (lo sfondo). Ma si può avere *when* con la lunga: {{en-GB|When I was walking home, it started to rain.}}' },
      { h: 'Quali verbi non si usano al continuo', b: 'I **verbi di stato** (know, like, love, want, believe, understand) di solito restano al **past simple**:\n- {{en-GB|I knew the answer.}} (non *I was knowing*)\n- {{en-GB|She wanted a coffee.}}\n\nPer le azioni compiute, completamente concluse, si usa il past simple: {{en-GB|I read a book yesterday.}} (finito) vs {{en-GB|I was reading a book at nine.}} (in corso).' },
      { h: 'Esempio guidato', b: 'Racconto: *Ieri mentre andavo al lavoro ho visto un amico. Lui parlava al telefono e non mi ha visto.*\n\n**Yesterday, while I was walking to work, I saw a friend. He was talking on the phone and didn’t see me.**\n\nControllo: sfondo in corso (was walking, was talking) + azioni complete (saw, didn’t see).' },
      { h: 'Errori comuni', b: '- *While I walked home, it rained* (con azione breve) → {{en-GB|While I was walking home, it started to rain.}}\n- *I was see him* → {{en-GB|I saw him.}}\n- *When I was arriving, he left* → {{en-GB|When I arrived, he left.}} (due azioni successive)\n- *I was knowing* → {{en-GB|I knew.}}\n- Dimenticare *was/were*: *I walking* → {{en-GB|I was walking.}}' },
      { h: 'Riepilogo', b: '- was/were + -ing: sfondo, azione in corso.\n- Past simple: azioni concluse e in sequenza.\n- when + azione breve, while + azione in corso.\n- I verbi di stato restano al past simple.' }
    ],
    exercises: [
      mc('I ___ TV when the phone rang.', ['watched', 'was watching', 'watching', 'am watching'], 1),
      mc('While she ___, he arrived.', ['was cooking', 'cooked', 'cooks', 'has cooked'], 0),
      fill('Complete: They ___ (play) football when it started to rain.', ['were playing'], 'Sfondo in corso: were + -ing.'),
      mc('We ___ the answer, so we passed.', ['were knowing', 'knew', 'were knowing about', 'knowing'], 1),
      order('Metti in ordine', ['I', 'was', 'walking', 'when', 'I', 'saw', 'him'], 'Was + -ing, when + past simple.'),
      mc('Which sentence describes a sequence of events?', ['I was opening the door and I was seeing a dog.', 'I opened the door and saw a dog.', 'I was open the door and saw a dog.', 'I opening the door and saw a dog.'], 1),
      listen('I was sleeping when you called.', 'en-GB', 'What was the speaker doing?', ['Working', 'Sleeping', 'Eating', 'Driving'], 1, 'Was sleeping = stava dormendo.')
    ],
    test: [
      mc('Choose the correct sentence.', ['When I was arriving, the film started.', 'When I arrived, the film was starting.', 'When I arrived, the film had already started.', 'While I arrived, the film started.'], 2),
      mc('What were you doing at 8 p.m. last night?', ['I watched a film.', 'I was watching a film.', 'I watch a film.', 'I was watch a film.'], 1),
      mc('«It was raining while we were having lunch.» Both actions…', ['happened at the same time', 'happened one after the other', 'are in the future', 'are finished before'], 0),
      fill('Complete: She ___ (not / listen) when the teacher spoke.', ['wasn’t listening', 'was not listening', 'wasnt listening'], 'Negativo del past continuous.'),
      mc('Which verb is NOT normally used in the continuous?', ['read', 'cook', 'know', 'walk'], 2)
    ],
    cards: [card('c1', 'stavo facendo', 'was / were doing', 'I was working.'), card('c2', 'mentre', 'while', 'While I was sleeping…'), card('c3', 'quando', 'when', 'When I arrived…'), card('c4', 'sfondo', 'background', 'the background of a story'),
      card('c5', 'interrompere', 'to interrupt', 'The phone interrupted my lunch.'), card('c6', 'squillare', 'to ring', 'The phone rang.'), card('c7', 'incidente', 'accident', 'We saw an accident.'), card('c8', 'raccontare', 'to tell a story', 'He told a funny story.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A strange evening', text: 'Last Friday I was cooking dinner when somebody knocked on the door. My husband was watching a football match, so I went to open it. A man was standing there. He was holding a big box. He said, “Sorry, wrong house,” and walked away. While I was closing the door, I noticed that the cat was missing. We looked everywhere, and in the end we found it. It was sleeping inside the box!',
      qs: [{ q: 'What was the speaker doing when somebody knocked?', o: ['Cooking dinner', 'Watching football', 'Sleeping', 'Opening a box'], a: 0, kind: 'explicit' }, { q: 'Where was the cat?', o: ['In a box', 'In the garden', 'On the sofa', 'At the neighbour’s'], a: 0, kind: 'explicit' }, { q: 'How does the speaker feel at the end?', o: ['Amused', 'Terrified', 'Angry', 'Bored'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'I was cooking when the phone rang.', lang: 'en-GB' }, { text: 'While we were walking, it started to rain.', lang: 'en-US' }, { text: 'What were you doing at nine?', lang: 'en-AU' }],
    shadowing: [{ text: 'I was having a shower when you called.', lang: 'en-GB', tip: 'Was debole /wəz/; accento su having e called.' }, { text: 'They were playing cards while it was raining.', lang: 'en-US', tip: 'Were debole /wər/.' }, { text: 'She wasn’t listening to the teacher.', lang: 'en-AU', tip: 'Wasn’t: /ˈwɒznt/ è forte.' }],
    speaking: [{ prompt: 'Tell what you were doing yesterday at 9 p.m. and what interrupted you.', model: 'Yesterday at nine I was watching a film when my friend called. I was enjoying it, so I didn’t answer at first.' }, { prompt: 'Describe a memory with background and events (use while, when).', model: 'Last summer I was swimming at the beach when I saw a dolphin. While I was looking at it, my brother shouted and the dolphin swam away.' }] });

  T({ id: 'eng-l1-defining-relative-basics', stage: 'L1', prereq: ['eng-l0-questions'], title: 'Frasi relative definenti: who, which, that, where', summary: 'Identificare una persona, una cosa o un luogo con who, which, that, where; omissione del pronome.',
    objectives: ['Scegliere who / which / that / where / whose', 'Capire quando il pronome relativo si può omettere', 'Evitare l’errore del pronome doppio (the man who he…)'],
    pages: [
      { h: 'Obiettivo', b: 'Una **frase relativa definente** dice *quale* persona o cosa intendiamo. Si usa spesso nel parlato: *la donna che abita accanto*, *il libro che ho letto*. In inglese il pronome cambia secondo il tipo di nome: **who** (persone), **which** (cose), **that** (entrambi), **where** (luoghi).' },
      { h: 'Who, which, that', b: '- **who** per persone: {{en-GB|The woman who lives next door is a nurse.}}\n- **which** per cose: {{en-GB|The book which is on the table is mine.}}\n- **that** per persone e cose (molto comune): {{en-GB|The film that we saw was great.}} {{en-GB|The man that called was your uncle.}}\n\nNon c’è virgola: la relativa è **necessaria** per identificare il nome.' },
      { h: 'Where, when, whose', b: '- **where** per luoghi: {{en-GB|This is the café where we met.}}\n- **when** per tempo: {{en-GB|I remember the day when we met.}}\n- **whose** = di cui, il cui: {{en-GB|She’s the girl whose brother is a famous singer.}}\n\nSi può anche dire *the café that we liked* (oggetto).' },
      { h: 'Soggetto o oggetto: si può omettere?', b: 'Se il pronome relativo è **soggetto** della relativa, **non si può omettere**:\n- {{en-GB|The man who lives here is a doctor.}} (who = soggetto di *lives*)\n\nSe è **oggetto**, si può **omettere**:\n- {{en-GB|The film (that) we saw was great.}} (we = soggetto, film = oggetto)\n- {{en-GB|The person (who) I met was kind.}}\n\nTest: dopo il pronome c’è un soggetto (we, I, she)? Allora il pronome è oggetto e si può togliere.' },
      { h: 'Preposizioni nelle relative', b: 'Nel parlato la preposizione va in fondo:\n- {{en-GB|This is the girl (that) I told you about.}}\n- {{en-GB|The hotel (which) we stayed at was lovely.}}\n\nNella forma formale: *the girl about whom I told you* (rara).\n\nCon *where* non si mette preposizione: *the hotel where we stayed* (non *the hotel where we stayed at*).' },
      { h: 'Esempio guidato', b: 'Unisci: *Ho un amico. Lui lavora a Londra.* → **I have a friend who works in London.**\n\nUnisci: *Questo è il libro. L’ho comprato ieri.* → **This is the book (that) I bought yesterday.**\n\nUnisci: *Questa è la città. Sono nato lì.* → **This is the city where I was born.**\n\nControllo: soggetto → who obbligatorio; oggetto → si può togliere.' },
      { h: 'Errori comuni', b: '- *The man who he lives here…* → {{en-GB|The man who lives here…}} (niente pronome doppio)\n- *The book what I read* → {{en-GB|The book that I read.}}\n- *The woman which called* → {{en-GB|The woman who called.}} (per persone: who)\n- *The hotel where we stayed at* → {{en-GB|The hotel where we stayed.}}\n- *The girl who’s brother…* → {{en-GB|The girl whose brother…}}' },
      { h: 'Riepilogo', b: '- who = persone, which = cose, that = persone/cose, where = luoghi, whose = possesso.\n- Pronome soggetto: obbligatorio; oggetto: facoltativo.\n- Nessun pronome in più: *the man who lives*, non *who he lives*.\n- Nel parlato preposizione in fondo.' }
    ],
    exercises: [
      mc('The woman ___ lives next door is a teacher.', ['which', 'who', 'whose', 'where'], 1),
      mc('This is the restaurant ___ we had dinner.', ['where', 'who', 'whose', 'what'], 0),
      mc('The film ___ we saw yesterday was boring. Which word is NOT possible?', ['that', 'which', 'what', '(no word)'], 2),
      fill('Complete: She’s the girl ___ brother is a doctor. (possession)', ['whose'], 'Whose = il cui.'),
      order('Metti in ordine', ['The', 'man', 'who', 'lives', 'here', 'is', 'my', 'uncle'], 'Who soggetto: non si omette.'),
      mc('Which sentence is correct?', ['The book who I read was good.', 'The book that I read was good.', 'The book what I read was good.', 'The book where I read was good.'], 1),
      listen('The man who called yesterday is my uncle.', 'en-GB', 'Who is the man?', ['A friend', 'The speaker’s uncle', 'A neighbour', 'A teacher'], 1, 'Who called yesterday = che ha chiamato ieri.')
    ],
    test: [
      mc('Can we omit the pronoun here? «The song (that) she sang was lovely.»', ['Yes, it is an object', 'No, it is a subject', 'No, never', 'Only after a comma'], 0),
      mc('Which sentence is wrong?', ['The man who lives here is kind.', 'The man who he lives here is kind.', 'The man that lives here is kind.', 'The man lives here is kind.'], 1),
      mc('«The shop ___ I bought my shoes is closed.»', ['which', 'where', 'who', 'whose'], 1),
      mc('Which pronoun is best for people in informal English?', ['which', 'what', 'who / that', 'where'], 2),
      fill('Complete: The people ___ live upstairs are noisy.', ['who', 'that'], 'Persone, soggetto: who / that.')
    ],
    cards: [card('c1', 'che (persone)', 'who', 'the man who called'), card('c2', 'che (cose)', 'which', 'the book which I read'), card('c3', 'che (persone/cose)', 'that', 'the film that we saw'), card('c4', 'dove', 'where', 'the café where we met'),
      card('c5', 'il cui', 'whose', 'a girl whose dad is a pilot'), card('c6', 'vicino di casa', 'neighbour', 'our new neighbour'), card('c7', 'proprio come', 'exactly', 'That’s exactly the one.'), card('c8', 'identificare', 'to identify', 'to identify a person')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'Describing people', text: 'My friend Sara is the girl who always sits near the window. She’s the one who writes poems. The café where we meet every Friday has very good cake. The man who owns it is called Joe. Last week she brought a book that I wanted to read, and she forgot to take it back home. Her brother, whose job is in New York, visits us once a year.',
      qs: [{ q: 'Who is Sara?', o: ['The girl who sits near the window', 'The owner of the café', 'A teacher', 'A brother of Joe'], a: 0, kind: 'explicit' }, { q: 'What does Sara do?', o: ['She writes poems', 'She cooks', 'She sings', 'She paints'], a: 0, kind: 'explicit' }, { q: 'How often does the group go to the café?', o: ['Every Friday', 'Every day', 'Once a year', 'Never'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'The woman who lives next door is a nurse.', lang: 'en-GB' }, { text: 'This is the café where we met.', lang: 'en-US' }, { text: 'The book that I read was wonderful.', lang: 'en-AU' }],
    shadowing: [{ text: 'The man who called is my uncle.', lang: 'en-GB', tip: 'Who: /huː/ debole nel ritmo.' }, { text: 'This is the film that I told you about.', lang: 'en-US', tip: 'That relativo: /ðət/ debole.' }, { text: 'She’s the girl whose brother is famous.', lang: 'en-AU', tip: 'Whose /huːz/, non confonderlo con who’s.' }],
    speaking: [{ prompt: 'Describe a friend using who, that and where.', model: 'My friend Paola is the person who always makes me laugh. She works in a bar where people love her coffee.' }, { prompt: 'Define three things or places using relative clauses.', model: 'A library is a place where you borrow books. A nurse is a person who looks after patients. A key is something that opens a door.' }] });

  /* ---------- L2 ---------- */
  T({ id: 'eng-l2-passive-advanced-forms', stage: 'L2', prereq: ['eng-l2-passive-relative'], title: 'Passivo avanzato: tutti i tempi, get-passive e causativo', summary: 'Passivo in tutti i tempi e coi modali; get + participio; have/get something done.',
    objectives: ['Formare il passivo in tutti i tempi e con i modali', 'Usare il get-passive e il causativo have / get something done', 'Scegliere quando usare il passivo e come inserire l’agente con by'],
    pages: [
      { h: 'Obiettivo', b: 'Il passivo sposta l’attenzione sull’**azione o sul risultato** e non su chi la compie. Si usa molto nella scrittura formale, nelle notizie e nei testi tecnici. Qui consolidi il passivo in tutti i tempi e aggiungi due strutture di livello B2: il **get-passive** e il **causativo** (*farsi fare qualcosa*).' },
      { h: 'Formula e tempi', b: '**be (al tempo giusto) + participio passato**\n- Present simple: {{en-GB|English is spoken here.}}\n- Present continuous: {{en-GB|The road is being repaired.}}\n- Past simple: {{en-GB|The window was broken.}}\n- Past continuous: {{en-GB|The house was being painted.}}\n- Present perfect: {{en-GB|The letter has been sent.}}\n- Past perfect: {{en-GB|The work had been finished.}}\n- Future: {{en-GB|The report will be completed tomorrow.}}\n- Future perfect: {{en-GB|It will have been done by Friday.}}' },
      { h: 'Modali e infinito', b: 'Dopo un modale: **modale + be + participio**\n- {{en-GB|The form must be signed.}}\n- {{en-GB|The problem can’t be solved quickly.}}\n- {{en-GB|He should have been told.}} (modale perfetto passivo)\n\nInfinito passivo: **to be + participio**: {{en-GB|I want to be invited.}} {{en-GB|She hates being ignored.}} (-ing passivo: *being + participio*).' },
      { h: 'Chi fa l’azione: by', b: 'L’agente si aggiunge con **by** solo se è utile o sorprendente:\n- {{en-GB|The novel was written by Jane Austen.}}\n- {{en-GB|The car was stolen.}} (non importa chi)\n\nUsa il passivo quando l’agente è sconosciuto, ovvio, o poco importante, oppure per un tono impersonale: {{en-GB|Mistakes were made.}}' },
      { h: 'Get-passive', b: '**get + participio** = passivo informale, spesso per eventi **improvvisi, accidentali o non voluti**:\n- {{en-GB|He got fired last week.}}\n- {{en-GB|My phone got stolen on the train.}}\n- {{en-GB|They are getting married in June.}}\n\nNon si usa per stati o in contesti formali; di solito non c’è un agente con *by*.' },
      { h: 'Causativo: have / get something done', b: 'Si usa per un servizio **fatto da altri** per noi:\n- **have + oggetto + participio**: {{en-GB|I had my hair cut yesterday.}}\n- **get + oggetto + participio** (più informale): {{en-GB|She’s getting her car repaired.}}\n- Presente: {{en-GB|We have the windows cleaned every month.}}\n- Futuro: {{en-GB|I’ll have the documents translated.}}\n\nSe il soggetto subisce un danno: {{en-GB|He had his wallet stolen.}} (non lo ha chiesto lui). Confronto: *I cut my hair* = lo faccio io.' },
      { h: 'Esempio guidato', b: 'Trasforma: *Il meccanico sta riparando la mia auto. Domani la riparerà del tutto.*\n\n- Passivo: **My car is being repaired. It will be repaired by tomorrow.**\n- Causativo: **I’m having my car repaired.**\n\nControllo: be + participio, tempo giusto; nel causativo soggetto = cliente.' },
      { h: 'Errori comuni', b: '- *It was happened* → {{en-GB|It happened.}} (i verbi intransitivi non hanno il passivo)\n- *The house built in 1900* → {{en-GB|was built in 1900.}}\n- *I cut my hair at the hairdresser’s* → {{en-GB|I had my hair cut at the hairdresser’s.}}\n- *She has repaired her car by a mechanic* → {{en-GB|She has had her car repaired.}}\n- *The report will be finish* → {{en-GB|will be finished.}}' },
      { h: 'Riepilogo', b: '- Passivo = be + participio, in ogni tempo e con i modali.\n- by + agente solo se importante.\n- get + participio: informale, spesso eventi imprevisti.\n- have / get + oggetto + participio: far fare qualcosa.' }
    ],
    exercises: [
      mc('The bridge ___ next year.', ['will build', 'will be built', 'will be building', 'is building'], 1),
      mc('The room ___ at the moment.', ['is cleaned', 'is being cleaned', 'was cleaning', 'cleans'], 1),
      fill('Complete: I had my phone ___ (repair) last week.', ['repaired'], 'Have + oggetto + participio.'),
      mc('Which sentence is NOT possible?', ['The accident was happened yesterday.', 'The window was broken.', 'The letter has been sent.', 'The form must be signed.'], 0, 'Happen è intransitivo: nessun passivo.'),
      order('Metti in ordine', ['She', 'got', 'her', 'hair', 'cut', 'yesterday'], 'Get + oggetto + participio.'),
      mc('He ___ by the police last night.', ['got stopped', 'got stop', 'was get stopped', 'stopped'], 0),
      listen('We’re having the kitchen painted next week.', 'en-GB', 'Who will paint the kitchen?', ['The speakers themselves', 'Somebody else', 'The neighbours', 'Nobody'], 1, 'Having + participio: lo fa un professionista.')
    ],
    test: [
      mc('Choose the correct passive: «They had finished the work.»', ['The work had finished.', 'The work was finished.', 'The work had been finished.', 'The work has been finished.'], 2),
      mc('«I had my car washed» means…', ['I washed it myself', 'Somebody washed it for me', 'My car was stolen', 'I will wash it'], 1),
      mc('Which sentence uses a get-passive correctly?', ['The documents get be signed.', 'She got promoted last month.', 'He got to promote.', 'They got promoting.'], 1),
      mc('«The report must ___ by Friday.»', ['complete', 'be completed', 'being completed', 'to be complete'], 1),
      fill('Complete: By next year the factory ___ (build). (future perfect passive: will have been ___)', ['built'], 'Participio di build: built.')
    ],
    cards: [card('c1', 'riparare', 'to repair', 'I’m having it repaired.'), card('c2', 'consegnare', 'to deliver', 'The parcel was delivered.'), card('c3', 'licenziare', 'to fire', 'He got fired.'), card('c4', 'rubare', 'to steal', 'My bag was stolen.'),
      card('c5', 'promuovere', 'to promote', 'She got promoted.'), card('c6', 'firmare', 'to sign', 'The form must be signed.'), card('c7', 'tradurre', 'to translate', 'I’ll have it translated.'), card('c8', 'farsi tagliare i capelli', 'to have your hair cut', 'I had my hair cut.'), card('c9', 'sposarsi', 'to get married', 'They are getting married.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A busy week', text: 'This week has been a nightmare. On Monday my laptop got stolen from the car, so I had to have a new one delivered. The office is being renovated, which means the whole floor is being painted and the windows are being replaced. Meanwhile, I’m having my apartment cleaned because I simply don’t have the time. My manager says the project must be finished by Friday, and I can’t see how it will be done.',
      qs: [{ q: 'What happened to the laptop?', o: ['It was stolen', 'It was repaired', 'It was sold', 'It was lent'], a: 0, kind: 'explicit' }, { q: 'What is being done to the office?', o: ['It is being renovated', 'It is being sold', 'It is being closed', 'It is being cleaned only'], a: 0, kind: 'explicit' }, { q: 'How does the speaker feel about the deadline?', o: ['Worried', 'Relaxed', 'Excited', 'Proud'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'The report has already been sent.', lang: 'en-GB' }, { text: 'I’m having my hair cut tomorrow.', lang: 'en-US' }, { text: 'He got fired after the meeting.', lang: 'en-AU' }],
    shadowing: [{ text: 'The road is being repaired at the moment.', lang: 'en-GB', tip: 'Is being: /ɪz ˈbiːɪŋ/; accento su repaired.' }, { text: 'I had my car serviced last week.', lang: 'en-US', tip: 'Accento su had e serviced.' }, { text: 'It must be done by Friday.', lang: 'en-AU', tip: 'Must be: /mʌst bi/ legati.' }],
    speaking: [{ prompt: 'Say three things you have done for you by others (hair, car, home).', model: 'I have my hair cut every two months. I had my laptop repaired last week. I’m getting my flat painted in the summer.' }, { prompt: 'Describe a place using the passive (what is made, built, spoken).', model: 'My town is known for its cheese. The cathedral was built in the fourteenth century, and it is visited by thousands of tourists every year.' }] });

  T({ id: 'eng-l2-conditionals-2-3-review', stage: 'L2', prereq: ['eng-l1-future-cond'], title: 'Condizionali: secondo e terzo, con ripasso', summary: 'If + past simple / would; if + past perfect / would have; consigli, unless, as long as, otherwise.',
    objectives: ['Distinguere zero, primo, secondo e terzo condizionale', 'Formare secondo e terzo condizionale senza errori di would', 'Usare unless, as long as, provided that e otherwise'],
    pages: [
      { h: 'Obiettivo', b: 'I condizionali sono quattro «tipi» principali. In questa lezione ripassiamo rapidamente **zero** e **primo** e lavoriamo in dettaglio su **secondo** (ipotesi irreale nel presente) e **terzo** (rimpianto nel passato), insieme alle parole che li arricchiscono: *unless, as long as, otherwise*.' },
      { h: 'Ripasso: zero e primo', b: '- **Zero** (verità generali): **if + present, present**: {{en-GB|If you heat ice, it melts.}}\n- **Primo** (possibile in futuro): **if + present, will + base**: {{en-GB|If it rains, we’ll stay at home.}}\n\nNella frase con **if** non si usa mai *will*: *If it will rain* è un errore.' },
      { h: 'Secondo condizionale', b: '**if + past simple, would + verbo base**\n\nSituazioni **irreali o improbabili** nel presente/futuro:\n- {{en-GB|If I won the lottery, I would buy a house.}}\n- {{en-GB|If I were you, I would apologise.}} (consiglio)\n- {{en-GB|What would you do if you lost your job?}}\n\nCon **be** si usa **were** per tutte le persone nello stile formale. In italiano: *Se vincessi alla lotteria, comprerei una casa.* Il verbo past non indica passato, ma **irrealtà**.' },
      { h: 'Terzo condizionale', b: '**if + past perfect, would have + participio**\n\nSituazione **impossibile nel passato** (rimpianto o critica):\n- {{en-GB|If I had studied harder, I would have passed the exam.}}\n- {{en-GB|If she hadn’t missed the bus, she wouldn’t have been late.}}\n- {{en-GB|Would you have gone if they had invited you?}}\n\nIn italiano: *Se avessi studiato di più, avrei passato l’esame.* Variante con **could / might have**: {{en-GB|If I had left earlier, I could have caught the train.}}' },
      { h: 'Unless, as long as, provided, otherwise', b: '- **unless** = a meno che non / se non (di significato negativo, mai con *not*): {{en-GB|I’ll go unless it rains.}} = *if it doesn’t rain*.\n- **as long as / provided (that)** = purché: {{en-GB|You can borrow it as long as you return it.}}\n- **otherwise** = altrimenti: {{en-GB|Hurry up, otherwise we’ll miss the train.}}\n- **if not** = *If not, we’ll leave.*\n- **in case** non è if: {{en-GB|Take an umbrella in case it rains.}}' },
      { h: 'Esempio guidato', b: 'Traduci: *Se avessi più soldi, viaggerei. Se avessi risparmiato, ora avrei più soldi.*\n\n- Presente irreale: **If I had more money, I would travel.**\n- Passato irreale: **If I had saved, I would have more money now.** (condizionale misto)\n\nControllo: past simple + would (secondo); past perfect + would have (terzo).' },
      { h: 'Errori comuni', b: '- *If I would have time, I would go.* → {{en-GB|If I had time, I would go.}}\n- *If I would have known, I would have come.* → {{en-GB|If I had known, I would have come.}}\n- *If I was you* (informale) → meglio {{en-GB|If I were you.}}\n- *Unless you don’t hurry…* → {{en-GB|Unless you hurry…}}\n- *If it will rain, I’ll stay.* → {{en-GB|If it rains, I’ll stay.}}\n- *I would have gone if I know.* → {{en-GB|if I had known.}}' },
      { h: 'Riepilogo', b: '- Zero: if + present, present. Primo: if + present, will.\n- Secondo: if + past simple, would + base.\n- Terzo: if + past perfect, would have + participio.\n- Mai would nella frase con if.\n- unless = if … not; as long as = purché; otherwise = altrimenti.' }
    ],
    exercises: [
      mc('If I ___ more time, I would learn Chinese.', ['have', 'had', 'would have', 'will have'], 1),
      mc('If they had left earlier, they ___ the train.', ['would catch', 'would have caught', 'will catch', 'caught'], 1),
      fill('Complete: I ___ (not / go) out unless the weather improves.', ['won’t go', 'will not go', 'wont go'], 'Unless con primo condizionale: will + base.'),
      mc('Which sentence is correct?', ['If I would see him, I’d tell him.', 'If I saw him, I’d tell him.', 'If I see him, I’d tell him yesterday.', 'If I had seen him, I would tell him.'], 1),
      order('Metti in ordine', ['If', 'I', 'were', 'you', ',', 'I', 'would', 'wait'], 'Consiglio: if I were you, I would…'),
      mc('Take your keys, ___ you will be locked out.', ['unless', 'otherwise', 'as long as', 'although'], 1),
      listen('If she had known, she would have called.', 'en-GB', 'Did she call?', ['Yes', 'No, she did not know', 'She called twice', 'She called later'], 1, 'Terzo condizionale: non sapeva, quindi non ha chiamato.')
    ],
    test: [
      mc('«If I had listened, I wouldn’t have made that mistake.» This is…', ['a regret about the past', 'a plan for tomorrow', 'a general truth', 'a polite request'], 0),
      mc('Which is the correct second conditional?', ['If I will win, I’ll celebrate.', 'If I won, I would celebrate.', 'If I win, I would celebrate.', 'If I had won, I would celebrate.'], 1),
      mc('«I’ll go to the party unless I’m ill.» means…', ['I’ll go if I’m not ill', 'I’ll go if I’m ill', 'I won’t go', 'I went already'], 0),
      mc('Which sentence has a mistake?', ['If I were rich, I’d travel.', 'If I had known, I would have told you.', 'If I would be rich, I’d travel.', 'You can stay as long as you are quiet.'], 2),
      fill('Complete: If you had asked me, I ___ (help) you.', ['would have helped', 'd have helped'], 'Terzo condizionale: would have + participio.')
    ],
    cards: [card('c1', 'a meno che', 'unless', 'I’ll go unless it rains.'), card('c2', 'purché', 'as long as', 'as long as you are happy'), card('c3', 'altrimenti', 'otherwise', 'Hurry, otherwise we’ll be late.'), card('c4', 'nel caso che', 'in case', 'Take a coat in case it’s cold.'),
      card('c5', 'vincere alla lotteria', 'to win the lottery', 'If I won the lottery…'), card('c6', 'scusarsi', 'to apologise', 'I’d apologise.'), card('c7', 'perdere il treno', 'to miss the train', 'I missed the train.'), card('c8', 'conseguenza', 'consequence', 'the consequences of a decision')],
    listening: [{ id: 'l1', lang: 'en-US', title: 'What if?', text: 'People often ask me what I would do if I could change one thing in my life. Well, if I had studied music at university, I would be a professional pianist now. But I didn’t, so I work in a bank. If I won a lot of money, I would open a music school. I wouldn’t stop working completely, though, unless I were very rich. My friend says I should take lessons again, otherwise I’ll never improve. He’s right, as long as I find the time.',
      qs: [{ q: 'What does the speaker do now?', o: ['He works in a bank', 'He is a pianist', 'He teaches music', 'He studies at university'], a: 0, kind: 'explicit' }, { q: 'What would he do with a lot of money?', o: ['Open a music school', 'Buy a piano only', 'Travel', 'Stop working at once'], a: 0, kind: 'explicit' }, { q: 'What does the speaker imply?', o: ['He regrets not studying music', 'He hates music', 'He has no friends', 'He is already rich'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'If I had more time, I would learn Spanish.', lang: 'en-GB' }, { text: 'If she had left earlier, she wouldn’t have missed the train.', lang: 'en-US' }, { text: 'You can borrow my car as long as you drive carefully.', lang: 'en-AU' }],
    shadowing: [{ text: 'If I were you, I would talk to her.', lang: 'en-GB', tip: 'I would → I’d /aɪd/; accento su talk.' }, { text: 'If I had known, I would have told you.', lang: 'en-US', tip: 'Would have → would’ve /wʊdəv/.' }, { text: 'I’ll go unless it rains.', lang: 'en-AU', tip: 'Unless: /ənˈles/, accento sulla seconda sillaba.' }],
    speaking: [{ prompt: 'Say what you would do with a free month and what you would have done differently last year.', model: 'If I had a free month, I would travel around Asia. If I had planned better last year, I would have taken a longer holiday.' }, { prompt: 'Give advice to a friend using if I were you and otherwise.', model: 'If I were you, I would book the tickets now, otherwise they will become more expensive. I wouldn’t wait unless you’re not sure.' }] });

  /* ---------- L3 ---------- */
  T({ id: 'eng-l3-inversion-emphasis', stage: 'L3', prereq: ['eng-l3-argument'], title: 'Inversione e enfasi: never, rarely, not only, hardly', summary: 'Avverbi negativi all’inizio della frase con inversione ausiliare-soggetto; so / such, only after, no sooner.',
    objectives: ['Applicare l’inversione dopo gli avverbi negativi (never, rarely, seldom, hardly, no sooner, not only)', 'Usare inversione nei condizionali (Had I known…, Should you need…)', 'Distinguere quando l’inversione è obbligatoria e quando è solo stilistica'],
    pages: [
      { h: 'Obiettivo', b: 'In inglese l’ordine normale è **soggetto + verbo**. Per dare **enfasi**, nei testi formali, nei discorsi e nella scrittura letteraria, certe espressioni (soprattutto con significato negativo) vengono messe all’inizio e provocano l’**inversione**: l’ausiliare passa **prima** del soggetto, come in una domanda.' },
      { h: 'Avverbi negativi', b: 'Struttura: **avverbio negativo + ausiliare + soggetto + verbo base/participio**\n- {{en-GB|Never have I seen such a beautiful place.}}\n- {{en-GB|Rarely does he complain.}}\n- {{en-GB|Seldom do we eat out.}}\n- {{en-GB|Little did she know that he was lying.}}\n- {{en-GB|Nowhere will you find a better deal.}}\n\nSe nella frase normale non c’è ausiliare, si inserisce **do/does/did**: *He rarely complains* → *Rarely does he complain.*' },
      { h: 'Hardly, no sooner, not only', b: '- **Hardly / Scarcely … when**: {{en-GB|Hardly had we arrived when it started to rain.}}\n- **No sooner … than**: {{en-GB|No sooner had she sat down than the phone rang.}} (con *than*, non *when*)\n- **Not only … but also**: {{en-GB|Not only did he forget the tickets, but he also lost the map.}}\n- **Not until**: {{en-GB|Not until I got home did I realise I had lost my keys.}}\n\nCon *hardly/no sooner* si usa il **past perfect** (azione precedente) e il past simple per l’azione successiva.' },
      { h: 'Only e so/such', b: '- **Only + espressione**: {{en-GB|Only then did I understand.}} / {{en-GB|Only after the exam did she relax.}} / {{en-GB|Only when you ask me will I help.}}\n- **So + aggettivo**: {{en-GB|So tired was he that he fell asleep at once.}}\n- **Such + nome**: {{en-GB|Such was the noise that nobody could sleep.}}\n\nQueste forme sono molto letterarie: si usano soprattutto per scrivere.' },
      { h: 'Inversione nei condizionali', b: 'Nei condizionali formali si può **omettere if** e invertire:\n- **Had** (3° tipo): {{en-GB|Had I known, I would have called.}} = *If I had known…*\n- **Were** (2° tipo): {{en-GB|Were I you, I would accept.}} = *If I were you…*\n- **Should** (1° tipo, formale): {{en-GB|Should you need help, please call.}} = *If you need…*\n\nSi trova in email formali e istruzioni.' },
      { h: 'Esempio guidato', b: 'Riscrivi con enfasi: *Non ho mai mangiato un piatto così buono.*\n\n- Normale: *I have never eaten such a good dish.*\n- Enfatico: **Never have I eaten such a good dish.**\n\nRiscrivi: *Ha appena aperto la porta quando è suonato il telefono.* → **No sooner had he opened the door than the phone rang.**\n\nControllo: avverbio negativo + ausiliare + soggetto.' },
      { h: 'Errori comuni', b: '- *Never I have seen…* → {{en-GB|Never have I seen…}}\n- *Rarely he complains* → {{en-GB|Rarely does he complain.}}\n- *No sooner had he arrived when…* → {{en-GB|…than…}}\n- *Not only he forgot…* → {{en-GB|Not only did he forget…}}\n- *Hardly I had finished…* → {{en-GB|Hardly had I finished…}}\n- Usare l’inversione in ogni frase: suona artificiale; serve solo per enfasi.' },
      { h: 'Riepilogo', b: '- Avverbio negativo in testa + ausiliare + soggetto.\n- Senza ausiliare: do/does/did.\n- hardly … when, no sooner … than, not only … but also.\n- Only + espressione, so/such per enfasi.\n- Had I / Were I / Should you: condizionali formali.' }
    ],
    exercises: [
      mc('Never ___ such a beautiful sunset.', ['I have seen', 'have I seen', 'I saw', 'did I seen'], 1),
      mc('Rarely ___ late for work.', ['he is', 'does he arrive', 'he arrives', 'arrives he'], 1),
      fill('Complete: No sooner had she arrived ___ the party started. (than/when)', ['than'], 'No sooner … than.'),
      mc('Not only ___ the exam, but he also won a prize.', ['he passed', 'did he pass', 'he did pass', 'passed he'], 1),
      order('Metti in ordine', ['Hardly', 'had', 'we', 'left', 'when', 'it', 'rained'], 'Hardly + had + soggetto + participio.'),
      mc('Which sentence is the formal version of «If you need help, call me»?', ['Should you need help, call me.', 'Do you need help, call me.', 'If should you need help, call me.', 'You should need help, call me.'], 0),
      listen('Little did he know that the plan would fail.', 'en-GB', 'What did he know about the plan?', ['He knew it would fail', 'He did not know it would fail', 'He changed the plan', 'He liked it'], 1, 'Little did he know = non sapeva affatto.')
    ],
    test: [
      mc('Which sentence is correct?', ['Seldom we go to the theatre.', 'Seldom do we go to the theatre.', 'Seldom we do go to the theatre.', 'Do seldom we go to the theatre.'], 1),
      mc('«Had I known, I would have helped.» equals…', ['If I knew, I would help.', 'If I had known, I would have helped.', 'If I know, I will help.', 'When I knew, I helped.'], 1),
      mc('Only after the meeting ___ the truth.', ['I learned', 'learned I', 'did I learn', 'I did learn'], 2),
      mc('«Not until midnight ___ home.»', ['he came', 'came he', 'did he come', 'he did come'], 2),
      fill('Complete: Under no circumstances ___ (you / open) this door.', ['should you open', 'must you open', 'can you open', 'will you open'], 'Under no circumstances + ausiliare + soggetto.')
    ],
    cards: [card('c1', 'mai (enfatico)', 'never', 'Never have I seen it.'), card('c2', 'raramente', 'rarely', 'Rarely does he speak.'), card('c3', 'appena … quando', 'hardly … when', 'Hardly had we arrived when…'), card('c4', 'non appena … che', 'no sooner … than', 'No sooner had I left than…'),
      card('c5', 'non solo … ma anche', 'not only … but also', 'Not only did he come, but also…'), card('c6', 'soltanto allora', 'only then', 'Only then did I understand.'), card('c7', 'in nessun caso', 'under no circumstances', 'Under no circumstances should you…'), card('c8', 'in nessun luogo', 'nowhere', 'Nowhere will you find it.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'A dramatic evening', text: 'Never had we felt so nervous. Hardly had the lights gone down when the music started, and no sooner had the singer appeared than the crowd began to scream. Not only did she sing all her famous songs, but she also played the piano. Only after the final song did I realise that I had been crying. Rarely do I go to concerts, but I will never forget that night.',
      qs: [{ q: 'What happened when the lights went down?', o: ['The music started', 'The crowd left', 'The singer cried', 'The show ended'], a: 0, kind: 'explicit' }, { q: 'What did the singer do besides singing?', o: ['Played the piano', 'Danced', 'Told jokes', 'Spoke to fans'], a: 0, kind: 'explicit' }, { q: 'How does the speaker feel about the concert?', o: ['Very moved', 'Disappointed', 'Indifferent', 'Angry'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'Never have I seen such a beautiful place.', lang: 'en-GB' }, { text: 'No sooner had she arrived than the phone rang.', lang: 'en-US' }, { text: 'Rarely does he complain about anything.', lang: 'en-AU' }],
    shadowing: [{ text: 'Not only did he arrive late, but he also forgot the tickets.', lang: 'en-GB', tip: 'Pausa dopo late; tono ascendente su but also.' }, { text: 'Only then did I understand what she meant.', lang: 'en-US', tip: 'Accento su only e understand.' }, { text: 'Had I known, I would have called you.', lang: 'en-AU', tip: 'Had I: /həd aɪ/, voce discendente alla fine.' }],
    speaking: [{ prompt: 'Describe a surprising experience using Never have I… and Only then did I…', model: 'Never have I been so surprised. Only then did I realise that the whole party was for me.' }, { prompt: 'Complain politely about a bad trip using Not only… and Hardly… when…', model: 'Not only was the hotel dirty, but the staff were also rude. Hardly had we checked in when we heard loud noise.' }] });

  T({ id: 'eng-l3-tenses-narrative-review', stage: 'L3', prereq: ['eng-l3-narrative'], title: 'Tempi nel racconto: perfect aspects e proposizioni temporali', summary: 'Past perfect (simple e continuous), present perfect, future perfect e le proposizioni temporali after, before, by the time, as soon as.',
    objectives: ['Usare past perfect e past perfect continuous per ordinare gli eventi in un racconto', 'Scegliere il tempo giusto dopo after, before, as soon as, by the time, until', 'Collegare i perfect aspects (present, past, future) in modo coerente'],
    pages: [
      { h: 'Obiettivo', b: 'Quando racconti, devi far capire **l’ordine** degli eventi e la **durata**. I tempi *perfect* (past perfect, present perfect, future perfect) servono a mostrare che un’azione è **precedente** a un’altra. Questa lezione li ripassa e li collega alle **frasi temporali** (*after, before, by the time, as soon as, until, once*).' },
      { h: 'Past perfect', b: '**had + participio** = azione **precedente** a un momento nel passato.\n- {{en-GB|When I arrived, the film had already started.}}\n- {{en-GB|She told me she had lost her keys.}}\n- {{en-GB|I didn’t go because I had seen it before.}}\n\nNella sequenza si ha: azione 1 (**had done**) → azione 2 (**did**). In italiano: *trapassato prossimo*.' },
      { h: 'Past perfect continuous', b: '**had been + -ing** = durata prima di un momento nel passato, o causa di una situazione:\n- {{en-GB|He was tired because he had been working all night.}}\n- {{en-GB|They had been waiting for an hour when the bus finally came.}}\n\nCon verbi di stato si usa il past perfect semplice: *I had known her for years*.' },
      { h: 'Frasi temporali: after, before, until', b: 'Per esprimere la sequenza si possono usare:\n- **after** + past perfect / past simple: {{en-GB|After she had finished, she went home.}} / {{en-GB|After she finished, she went home.}} (stesso senso).\n- **before** + past simple: {{en-GB|Before he left, he had locked the door.}}\n- **as soon as / once**: {{en-GB|As soon as I got home, I called you.}}\n- **until / by the time**: {{en-GB|By the time we got there, they had left.}} / {{en-GB|I waited until she had finished.}}\n\nCon **by the time** si usa il past perfect nella principale (passato) e il present nella forma futura.' },
      { h: 'Present e future perfect nei contesti', b: '- **Present perfect**: collega passato e presente: {{en-GB|I’ve lost my keys, so I can’t get in.}}\n- **Future perfect**: completata prima di un momento futuro: {{en-GB|By the time you arrive, I’ll have cooked dinner.}}\n\nNelle temporali sul futuro si usa il present: {{en-GB|I’ll call you as soon as I finish.}} / {{en-GB|I’ll leave after I have finished.}}\n\nMai *will* dopo when, after, before, as soon as, until, by the time.' },
      { h: 'Esempio guidato', b: 'Racconta: *Quando sono arrivato alla stazione, il treno era già partito. Avevo aspettato un’ora quando è arrivata la mia amica.*\n\n**When I got to the station, the train had already left. I had been waiting for an hour when my friend arrived.**\n\nControllo: had left (azione precedente), had been waiting (durata), arrived (azione principale).' },
      { h: 'Errori comuni', b: '- *When I arrived, the film started already.* → {{en-GB|had already started.}}\n- *After I will finish…* → {{en-GB|After I finish…}}\n- *By the time we arrived, they were left.* → {{en-GB|had left.}}\n- *He had been know her.* → {{en-GB|He had known her.}}\n- *I have seen him yesterday.* → {{en-GB|I saw him yesterday.}} (con tempo finito: past simple)\n- Usare il past perfect ovunque: serve solo per l’azione precedente.' },
      { h: 'Riepilogo', b: '- had + participio: azione precedente nel passato.\n- had been + -ing: durata prima di un momento passato.\n- after / before / as soon as / by the time collegano gli eventi.\n- Futuro: present dopo le congiunzioni, will have + participio per la scadenza.\n- Ordine degli eventi + durata = tempi perfect.' }
    ],
    exercises: [
      mc('When we arrived, the concert ___.', ['already started', 'had already started', 'was already start', 'has already started'], 1),
      mc('She was exhausted because she ___ all day.', ['had been working', 'worked', 'has worked', 'was worked'], 0),
      fill('Complete: By the time he called, I ___ (leave) the office.', ['had left'], 'Azione precedente: past perfect.'),
      mc('I’ll text you as soon as I ___ home.', ['will get', 'get', 'would get', 'am getting'], 1),
      order('Metti in ordine', ['They', 'had', 'been', 'waiting', 'for', 'an', 'hour'], 'Past perfect continuous.'),
      mc('Which sentence is correct?', ['After I will finish, I’ll call you.', 'After I finish, I’ll call you.', 'After I would finish, I’ll call you.', 'After I finished, I’ll call you tomorrow.'], 1),
      listen('By the time the doctor arrived, the patient had recovered.', 'en-GB', 'What had happened before the doctor arrived?', ['The patient had recovered', 'The patient had left', 'The doctor had gone', 'Nothing'], 0, 'Past perfect: azione precedente.')
    ],
    test: [
      mc('Which sentence shows that the train left first?', ['The train left when I arrived.', 'The train had left when I arrived.', 'The train was leaving when I arrived.', 'The train leaves when I arrived.'], 1),
      mc('«I had been studying for hours, so I was tired.» The past perfect continuous shows…', ['duration before a past moment', 'a future plan', 'a habit now', 'a single short action'], 0),
      mc('By next June I ___ here for ten years.', ['will work', 'will have worked', 'work', 'have worked'], 1),
      mc('Which sentence is wrong?', ['I’ll leave once I finish.', 'I’ll leave when I will finish.', 'I’ll leave before it rains.', 'I’ll leave after I’ve eaten.'], 1),
      fill('Complete: She told me she ___ (never / see) the sea before.', ['had never seen', 'd never seen'], 'Riportato nel passato: past perfect.')
    ],
    cards: [card('c1', 'trapassato', 'past perfect', 'He had left.'), card('c2', 'già', 'already', 'It had already started.'), card('c3', 'non appena', 'as soon as', 'as soon as I arrive'), card('c4', 'una volta che', 'once', 'once you finish'),
      card('c5', 'entro il momento in cui', 'by the time', 'By the time we arrived…'), card('c6', 'fino a quando', 'until', 'until she came back'), card('c7', 'nel frattempo', 'meanwhile', 'Meanwhile, I was waiting.'), card('c8', 'alla fine', 'eventually', 'Eventually, the bus came.')],
    listening: [{ id: 'l1', lang: 'en-GB', title: 'The missed flight', text: 'By the time I reached the airport, the check-in desk had already closed. I had been running for ten minutes, and my phone had died, so I couldn’t call anyone. As soon as I understood the situation, I sat down and booked another flight. After I had paid, I realised that I had left my passport at home. Eventually, I managed to catch a later flight. By next week, I’ll have forgotten the whole story, I hope!',
      qs: [{ q: 'What had happened when the speaker reached the airport?', o: ['The check-in desk had closed', 'The flight had landed', 'The speaker’s phone was working', 'The passport was lost'], a: 0, kind: 'explicit' }, { q: 'What did the speaker realise after paying?', o: ['The passport was at home', 'The phone was broken', 'The flight was cancelled', 'The ticket was free'], a: 0, kind: 'explicit' }, { q: 'How does the speaker feel at the end?', o: ['Relieved but embarrassed', 'Furious', 'Proud', 'Calm'], a: 0, kind: 'implicit' }] }],
    dictation: [{ text: 'When I arrived, the film had already started.', lang: 'en-GB' }, { text: 'She had been waiting for an hour when he called.', lang: 'en-US' }, { text: 'I’ll phone you as soon as I get home.', lang: 'en-AU' }],
    shadowing: [{ text: 'By the time we got there, they had already left.', lang: 'en-GB', tip: 'Had: forma debole /əd/; accento su there e left.' }, { text: 'He had been working all night.', lang: 'en-US', tip: 'Had been: /həd bɪn/ legati.' }, { text: 'After she had finished, she went home.', lang: 'en-AU', tip: 'Pausa dopo finished.' }],
    speaking: [{ prompt: 'Tell a short story about a bad day using past perfect and past simple.', model: 'By the time I got to work, the meeting had already started. I had forgotten my laptop, and I had been running for ten minutes.' }, { prompt: 'Say what you will have achieved by the end of next year.', model: 'By the end of next year I will have finished my course, and I will have been working in my new job for six months.' }] });
})(window.ST = window.ST || {});
